export default {async fetch(request,env){const url=new URL(request.url);try{if(url.pathname.startsWith("/api/")){const user=await currentUser(env,request);return await api(request,env,user,url);}if(request.method!=="GET")return new Response("Not found",{status:404});if(url.pathname==="/")return new Response(boardPage,{headers:securityHeaders({"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store"})});if(url.pathname==="/completed")return new Response(completedPage,{headers:securityHeaders({"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store"})});if(url.pathname==="/admin")return new Response(adminPage,{headers:securityHeaders({"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store"})});return new Response("Not found",{status:404});}catch(error){console.error(error);if(url.pathname.startsWith("/api/"))return json({error:"The task board is temporarily unavailable"},500);return new Response("Company Task Board is temporarily unavailable.",{status:500,headers:securityHeaders({"Content-Type":"text/plain; charset=utf-8"})});}}};
